"""Build a bilingual, start-to-finish presentation using only fictional content."""
import json
import html
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / 'skills/ppt-to-html/scripts'))
from build_deck import build


def deck(language):
    en = language == 'en'
    def t(ko, english):
        return english if en else ko
    definitions = [
        ('agenda', '목차', 'Contents', '전체 발표를 처음부터 끝까지', 'A complete presentation, from opening to conclusion', 'flow', 'none', [
            ('01 · 개요', '01 · Overview', '목적과 검토 범위를 맞춥니다.', 'Align on the objective and scope.'),
            ('02 · 본문', '02 · Main discussion', '현황, 분석, 실행안을 설명합니다.', 'Explain the baseline, analysis and proposed actions.'),
            ('03 · 타임라인과 결론', '03 · Timeline and conclusion', '실행 순서를 제시하고 의사결정과 다음 행동을 정리합니다.', 'Show the implementation sequence, then close with a decision and next steps.')]),
        ('overview', '개요', 'Overview', '가상 마케팅 캠페인의 다음 실험을 결정합니다', 'Decide the next experiment for a fictional campaign', 'cards', 'points', [
            ('목적', 'Objective', '전환 흐름을 검토하고 개선 실험을 제안합니다.', 'Review the conversion journey and propose an experiment.'),
            ('범위', 'Scope', '가상 단일 캠페인의 집계값만 사용합니다.', 'Use aggregate counts from one fictional campaign.'),
            ('판단 기준', 'Decision rule', '추가 예산 승인 전 측정 기준과 검토일을 합의합니다.', 'Agree on measurement and review dates before approving extra budget.')]),
        ('baseline', '본문 · 현황', 'Main discussion · Baseline', '도달에서 구매까지 같은 캠페인의 흐름을 확인합니다', 'Trace one campaign from reach to purchase', 'compare', 'points', [
            ('도달', 'Reach', '1,500명 · 중복 제거한 가상 도달 인원', '1,500 people · fictional deduplicated audience'),
            ('클릭', 'Clicks', '300회 · 캠페인 클릭 이벤트', '300 events · campaign click events'),
            ('구매', 'Purchases', '45건 · 캠페인 귀속 구매 이벤트', '45 events · attributed purchase events')]),
        ('analysis', '본문 · 분석', 'Main discussion · Analysis', '지표마다 다른 분모를 명확히 표시합니다', 'Make each metric denominator explicit', 'compare', 'lines', [
            ('구매 / 클릭', 'Purchases / clicks', '15.0% = 45건 ÷ 300회 × 100', '15.0% = 45 purchases / 300 clicks × 100'),
            ('구매 / 도달', 'Purchases / reach', '3.0% = 45건 ÷ 1,500명 × 100', '3.0% = 45 purchases / 1,500 people × 100'),
            ('해석 한계', 'Interpretation limit', '이벤트와 인원의 비율이며 개인별 구매 확률이나 인과 효과가 아닙니다.', 'These event-to-audience ratios do not establish individual purchase probability or causal impact.')]),
        ('proposal', '본문 · 실행안', 'Main discussion · Proposed actions', '측정 후 실험을 진행하고 결과를 검토합니다', 'Measure first, run the experiment and review the results', 'flow', 'lines', [
            ('측정 정의', 'Define measurement', '클릭·구매의 집계 범위와 귀속 기준을 먼저 고정합니다.', 'Fix the aggregation scope and attribution rules first.'),
            ('메시지 실험', 'Test messaging', '두 메시지를 비교하되 예산과 기간 조건을 맞춥니다.', 'Compare two messages under matched budget and period conditions.'),
            ('판단 보류', 'Defer the decision', '실험 결과가 나오기 전에는 개선 효과를 확정하지 않습니다.', 'Do not claim an improvement before experimental results are available.')]),
        ('timeline', '타임라인', 'Timeline', '4주 실행 계획과 확인 시점', 'A four-week implementation plan with review gates', 'flow', 'planes', [
            ('1주 · 정의', 'Week 1 · Define', '지표·필터·데이터 수집 조건을 합의합니다.', 'Agree on metrics, filters and data collection.'),
            ('2주 · 준비', 'Week 2 · Prepare', '메시지 두 안과 측정 화면을 점검합니다.', 'Check two message variants and measurement views.'),
            ('3주 · 실행', 'Week 3 · Run', '합의한 조건으로 가상 실험을 진행합니다.', 'Run the illustrative experiment under agreed conditions.'),
            ('4주 · 검토', 'Week 4 · Review', '결과와 한계를 검토한 뒤 다음 단계를 결정합니다.', 'Review results and limitations before choosing the next step.')]),
        ('conclusion', '결론', 'Conclusion', '오늘 합의할 것과 다음 행동', 'The decision today and the next action', 'cards', 'none', [
            ('확인한 현황', 'Baseline reviewed', '클릭 300회, 구매 45건, 구매/클릭 15.0%인 가상 사례입니다.', 'Fictional baseline: 300 clicks, 45 purchases, purchases/clicks of 15.0%.'),
            ('요청하는 결정', 'Decision requested', '추가 성과를 약속하지 않고 4주 검증 계획을 검토합니다.', 'Review the four-week validation plan without promising additional performance.'),
            ('다음 행동', 'Next action', '담당자와 측정 정의를 정한 뒤 실험 준비를 시작합니다.', 'Assign an owner and agree on measurement before preparing the experiment.')]),
    ]
    scenes = []
    for i, (id_, ko, english, lead_ko, lead_en, layout, motion, items) in enumerate(definitions, 1):
        scenes.append(dict(id=id_, title=t(ko, english), eyebrow=f'{i:02d} / 07 · '+t('전체 발표 예제', 'Complete presentation example'),
                           lead=t(lead_ko, lead_en), layout=layout, motion=motion,
                           motion_caption=t('설명용 개념 모션 · 성과 예측 아님', 'Illustrative motion · not a performance forecast'),
                           items=[dict(label=t(a,b), body=t(c,d)) for a,b,c,d in items],
                           message=t('목차, 개요, 본문, 타임라인, 결론을 모두 담은 7장 전체 발표입니다.', 'This complete seven-scene presentation includes contents, overview, main discussion, timeline and conclusion.'),
                           source=t('새로 작성한 가상 데이터 · examples/full-presentation/README.ko.md', 'New fictional data · examples/full-presentation/README.md'), duration=10))
    return dict(title=t('가상 캠페인 검토 · 처음부터 끝까지', 'Fictional campaign review · from start to finish'), language=language,
                settings=dict(width=1600, height=900, font='system', motion='key', playback='both', end='stop'), scenes=scenes)


def render(language):
    en = language == 'en'
    def t(ko, english): return english if en else ko
    title=t('가상 캠페인 검토 · 전체 발표 예제','Fictional campaign review · complete presentation')
    labels={
        'agenda':t('목차','Contents'),'overview':t('개요','Overview'),'baseline':t('현황','Baseline'),
        'analysis':t('분석','Analysis'),'proposal':t('실행안','Action plan'),'timeline':t('타임라인','Timeline'),'conclusion':t('결론','Conclusion')}
    slides=[
      ('agenda',t('전체 발표의 흐름','Complete presentation flow'),t('목차부터 결론까지 7개 장면으로 의사결정 과정을 설명합니다.','Seven scenes cover the full decision process from contents to conclusion.'),f'''<div class="agenda-map">
        <div class="agenda-line"></div>
        <div class="agenda-node hot"><b>01</b><span>{labels['overview']}</span><small>{t('목적과 범위','Objective and scope')}</small></div>
        <div class="agenda-node"><b>02</b><span>{t('본문 3장','Three discussion scenes')}</span><small>{t('현황, 분석, 실행안','Baseline, analysis, action')}</small></div>
        <div class="agenda-node"><b>03</b><span>{labels['timeline']}</span><small>{t('4주 검증 계획','Four-week validation')}</small></div>
        <div class="agenda-node"><b>04</b><span>{labels['conclusion']}</span><small>{t('결정과 다음 행동','Decision and next action')}</small></div>
        <div class="orbit"><i></i><i></i><i></i><strong>7</strong><span>{t('장 전체','scenes')}</span></div>
      </div>'''),
      ('overview',t('검토 목적과 판단 기준','Review objective and decision rule'),t('가상 캠페인의 전환 흐름을 확인하고 다음 실험의 조건을 합의합니다.','Review a fictional campaign funnel and agree on the conditions for the next experiment.'),f'''<div class="split"><div class="brief">
        <p class="question">{t('오늘 결정할 내용','Decision for today')}</p><h3>{t('4주 메시지 실험을 준비할 것인가','Should we prepare a four-week messaging experiment?')}</h3>
        <div class="principles"><span><b>01</b>{t('집계 범위 고정','Fix aggregation scope')}</span><span><b>02</b>{t('분모 정의 확인','Confirm denominators')}</span><span><b>03</b>{t('결과 전 판단 보류','Wait for results')}</span></div>
      </div><div class="decision-wheel"><div class="ring r1"></div><div class="ring r2"></div><div class="ring r3"></div><div class="wheel-core"><strong>{t('검증','TEST')}</strong><span>{t('측정 후 결정','Measure, then decide')}</span></div><div class="sat s1">{t('도달','Reach')}</div><div class="sat s2">{t('클릭','Clicks')}</div><div class="sat s3">{t('구매','Purchases')}</div></div></div>'''),
      ('baseline',t('캠페인 전환 현황','Campaign conversion baseline'),t('같은 가상 캠페인의 도달, 클릭, 구매를 하나의 흐름으로 비교합니다.','Compare reach, clicks and purchases from the same fictional campaign.'),f'''<div class="split chart-slide"><div class="narrative"><span class="tag">FICTIONAL DATA</span><h3>{t('도달 이후 클릭은 20.0%, 클릭 이후 구매는 15.0%','Click rate is 20.0% of reach, and purchase rate is 15.0% of clicks')}</h3><p>{t('구매/도달은 3.0%입니다. 인원과 이벤트 단위가 다르므로 각 단계의 분모를 별도로 표시합니다.','Purchases/reach is 3.0%. Audience and event units differ, so every stage names its denominator.')}</p><div class="metric-row"><span><b>1,500</b>{t('명 도달','people reached')}</span><span><b>300</b>{t('회 클릭','click events')}</span><span><b>45</b>{t('건 구매','purchases')}</span></div></div>
      <div class="funnel"><div class="f-row f1"><label>{t('도달','Reach')}<small>100%</small></label><i style="--w:100%"></i><b>1,500</b></div><div class="f-row f2"><label>{t('클릭','Clicks')}<small>20.0%</small></label><i style="--w:64%"></i><b>300</b></div><div class="f-row f3"><label>{t('구매','Purchases')}<small>15.0% of clicks</small></label><i style="--w:38%"></i><b>45</b></div><div class="pulse-dot"></div></div></div>'''),
      ('analysis',t('주차별 흐름과 채널 차이','Weekly trend and channel differences'),t('총합만 보지 않고 주차 흐름과 채널별 전환 구조를 함께 확인합니다.','Review weekly movement and channel conversion structure instead of relying on totals alone.'),f'''<div class="analysis-grid"><div class="trend"><div class="chart-head"><b>{t('주차별 클릭과 구매','Weekly clicks and purchases')}</b><span>{t('단위: 이벤트','Unit: events')}</span></div><svg viewBox="0 0 720 330" aria-label="{t('4주 클릭 및 구매 가상 추이','Fictional four-week clicks and purchases trend')}"><g class="grid"><path d="M70 55H680M70 120H680M70 185H680M70 250H680"/></g><g class="bars"><rect x="115" y="105" width="56" height="145"/><rect x="260" y="82" width="56" height="168"/><rect x="405" y="66" width="56" height="184"/><rect x="550" y="48" width="56" height="202"/></g><path class="line" d="M143 218 L288 210 L433 195 L578 178"/><g class="dots"><circle cx="143" cy="218" r="8"/><circle cx="288" cy="210" r="8"/><circle cx="433" cy="195" r="8"/><circle cx="578" cy="178" r="8"/></g><g class="axis-label"><text x="125" y="285">W1</text><text x="270" y="285">W2</text><text x="415" y="285">W3</text><text x="560" y="285">W4</text></g></svg><div class="legend"><i></i>{t('클릭','Clicks')}<i></i>{t('구매','Purchases')}</div></div>
      <div class="channel"><div class="chart-head"><b>{t('채널별 구매/클릭','Purchases / clicks by channel')}</b><span>{t('분모: 채널별 클릭','Denominator: clicks by channel')}</span></div><div class="radar"><div class="radar-grid"></div><div class="radar-shape"></div><span class="ra">Search<br><b>18%</b></span><span class="rb">Social<br><b>12%</b></span><span class="rc">Email<br><b>16%</b></span></div><p>{t('수치는 시각화 기능을 보여주기 위한 가상 값입니다.','Figures are fictional and only demonstrate the visualization.')}</p></div></div>'''),
      ('proposal',t('4주 메시지 실험 설계','Four-week messaging experiment design'),t('비교 조건을 먼저 고정하고 동일한 측정 정의로 두 안을 검토합니다.','Fix comparison conditions first and evaluate both variants under one measurement definition.'),f'''<div class="experiment"><div class="exp-source"><span>{t('동일 대상','Same audience')}</span><b>1,200</b><small>{t('가상 표본','fictional sample')}</small></div><div class="stream"><i></i><i></i><i></i><i></i></div><div class="variant va"><em>A</em><h3>{t('기능 중심 메시지','Feature-focused message')}</h3><div class="mini-bars"><i style="--h:54%"></i><i style="--h:68%"></i><i style="--h:61%"></i><i style="--h:74%"></i></div><p>{t('예산과 노출 기간 동일','Same budget and exposure period')}</p></div><div class="variant vb"><em>B</em><h3>{t('문제 해결 메시지','Problem-solving message')}</h3><div class="mini-bars"><i style="--h:48%"></i><i style="--h:72%"></i><i style="--h:77%"></i><i style="--h:82%"></i></div><p>{t('성과 차이는 아직 미확정','Performance difference is not yet known')}</p></div><div class="gate"><b>{t('판단 기준','Decision gate')}</b><span>{t('구매/클릭, 표본수, 측정 오류를 함께 검토','Review purchases/clicks, sample size and measurement errors')}</span></div></div>'''),
      ('timeline',t('4주 실행 타임라인','Four-week implementation timeline'),t('준비, 실행, 검토 시점을 구분하고 각 단계의 확인 항목을 명시합니다.','Separate preparation, execution and review, with a clear check at each stage.'),f'''<div class="gantt"><div class="g-head"><span></span><b>W1</b><b>W2</b><b>W3</b><b>W4</b></div><div class="g-row"><strong>{t('측정 정의','Measurement')}</strong><i class="gbar b1"></i><small>{t('분모와 필터 승인','Approve denominators and filters')}</small></div><div class="g-row"><strong>{t('소재 준비','Creative setup')}</strong><i class="gbar b2"></i><small>{t('두 메시지와 화면 점검','Check both messages and views')}</small></div><div class="g-row"><strong>{t('실험 실행','Experiment')}</strong><i class="gbar b3"></i><small>{t('동일 조건으로 운영','Run under matched conditions')}</small></div><div class="g-row"><strong>{t('결과 검토','Review')}</strong><i class="gbar b4"></i><small>{t('한계 포함 의사결정','Decide with limitations visible')}</small></div><div class="milestones"><span style="--x:14%">{t('정의 확정','Definition')}</span><span style="--x:39%">{t('실행 시작','Launch')}</span><span style="--x:89%">{t('결과 회의','Review')}</span></div></div>'''),
      ('conclusion',t('의사결정과 다음 행동','Decision and next action'),t('현재 수치는 현황을 설명하며 실험 성과를 예측하지 않습니다.','Current figures describe the baseline and do not predict experiment performance.'),f'''<div class="closing"><div class="close-main"><span>{t('요청하는 결정','DECISION REQUEST')}</span><h3>{t('측정 정의를 확정한 뒤 4주 실험 준비를 시작합니다','Confirm the measurement definition, then begin preparing the four-week experiment')}</h3><p>{t('담당자와 검토일을 지정하고 결과가 나오기 전에는 개선 효과를 확정하지 않습니다.','Assign an owner and review date. Do not claim improvement before results are available.')}</p></div><div class="close-ring"><div><b>15.0%</b><span>{t('구매/클릭<br>가상 기준값','Purchases/clicks<br>fictional baseline')}</span></div></div><div class="next"><span><b>01</b>{t('측정 정의 승인','Approve measurement')}</span><span><b>02</b>{t('실험 담당자 지정','Assign owner')}</span><span><b>03</b>{t('4주차 결과 검토','Review in week four')}</span></div></div>''')]
    slide_html=''.join(f'''<section class="slide" data-id="{sid}" aria-label="{html.escape(label)}"><header><span class="chapter">{i:02d} / 07 · {labels[sid]}</span><span class="fictional">FICTIONAL DATA</span><h1>{html.escape(label)}</h1><p>{html.escape(lead)}</p></header><main>{body}</main><footer><b>{html.escape(title)}</b><span>{i:02d} / 07</span></footer></section>''' for i,(sid,label,lead,body) in enumerate(slides,1))
    controls=t('이전','Previous'),t('다음','Next'),t('자동 재생','Auto play'),t('처음부터','Restart'),t('인쇄 / PDF','Print / PDF')
    data=json.dumps({'language':language,'count':len(slides)},ensure_ascii=False).replace('<','\\u003c')
    page=f'''<!doctype html><html lang="{language}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{html.escape(title)}</title><style>
:root{{--orange:#ee7a22;--deep:#24342a;--green:#7fab61;--blue:#3e7fa8;--paper:#f7f6f1;--line:#d8ddd7;--muted:#6f756f}}*{{box-sizing:border-box}}html,body{{margin:0;height:100%;overflow:hidden;background:#20231f;font-family:Arial,"Malgun Gothic",sans-serif;color:#1d241f}}#viewport{{position:absolute;inset:0 0 72px;display:grid;place-items:center;overflow:hidden}}#deck{{position:relative;width:1600px;height:900px;transform-origin:center center;background:var(--paper);overflow:hidden}}.slide{{position:absolute;inset:0;background:linear-gradient(135deg,#faf9f4,#f3f5ee);opacity:0;visibility:hidden;transition:opacity .55s;overflow:hidden}}.slide.on{{opacity:1;visibility:visible}}header{{position:absolute;left:72px;top:50px;width:1456px}}.chapter{{color:#42624c;font-weight:800;font-size:17px;letter-spacing:.04em}}.fictional{{float:right;border:1px solid #9dad9e;color:#536357;padding:5px 12px;border-radius:14px;font-size:12px;letter-spacing:.13em}}h1{{font-size:46px;line-height:1.15;margin:20px 0 8px;letter-spacing:-.04em}}header p{{font-size:20px;color:#5f675f;margin:0;max-width:1240px}}main{{position:absolute;left:72px;right:72px;top:205px;bottom:84px}}footer{{position:absolute;left:72px;right:72px;bottom:28px;border-top:1px solid var(--line);padding-top:14px;display:flex;justify-content:space-between;color:#758078;font-size:13px}}footer b{{font-weight:600}}.agenda-map{{position:relative;height:100%;display:grid;grid-template-columns:repeat(3,1fr);gap:28px;align-items:center;padding-right:340px}}.agenda-line{{position:absolute;left:8%;right:29%;top:50%;height:4px;background:linear-gradient(90deg,var(--orange),#eeb36f,var(--green));border-radius:4px}}.agenda-node{{position:relative;background:#fff;border:1px solid var(--line);border-top:7px solid #aeb9ad;padding:34px 26px;height:210px;box-shadow:0 12px 28px #28372d13;transform:translateY(20px);transition:.55s}}.slide.on .agenda-node{{transform:none}}.agenda-node:nth-child(3){{transition-delay:.12s}}.agenda-node:nth-child(4){{transition-delay:.24s}}.agenda-node.hot{{border-top-color:var(--orange)}}.agenda-node b{{font-size:14px;color:var(--orange)}}.agenda-node span{{display:block;font-size:24px;font-weight:800;margin:24px 0 12px}}.agenda-node small{{font-size:16px;color:var(--muted)}}.orbit{{position:absolute;right:34px;top:112px;width:260px;height:260px;border:1px solid #cbd4ca;border-radius:50%;display:grid;place-items:center}}.orbit:before,.orbit:after{{content:"";position:absolute;border:1px solid #cbd4ca;border-radius:50%;inset:32px}}.orbit:after{{inset:66px;background:#fff}}.orbit strong{{font-size:88px;color:var(--orange);z-index:2}}.orbit span{{position:absolute;top:172px;z-index:2;font-weight:800}}.orbit i{{position:absolute;width:15px;height:15px;background:var(--orange);border-radius:50%;animation:orbit 5s linear infinite;transform-origin:130px 0;left:122px;top:122px}}.orbit i:nth-child(2){{animation-delay:-1.7s;background:var(--green)}}.orbit i:nth-child(3){{animation-delay:-3.4s;background:var(--blue)}}@keyframes orbit{{to{{transform:rotate(360deg) translateX(130px)}}}}.split{{height:100%;display:grid;grid-template-columns:47% 53%;gap:48px;align-items:center}}.brief{{padding-right:35px}}.question,.tag{{display:inline-block;color:#a94c12;background:#fdebd9;padding:8px 13px;border-radius:4px;font-weight:800;font-size:14px}}.brief h3,.narrative h3{{font-size:38px;line-height:1.3;margin:24px 0 44px;letter-spacing:-.035em}}.principles{{display:grid;gap:12px}}.principles span{{display:flex;align-items:center;background:#fff;border-bottom:1px solid var(--line);padding:18px;font-size:18px;font-weight:700}}.principles b{{color:var(--orange);margin-right:18px}}.decision-wheel{{position:relative;width:560px;height:560px;margin:auto}}.ring{{position:absolute;border:2px solid #cfd8ce;border-radius:50%;inset:0;animation:spin 18s linear infinite}}.r2{{inset:68px;border-style:dashed;animation-direction:reverse}}.r3{{inset:136px;border-color:#f0b481}}@keyframes spin{{to{{transform:rotate(360deg)}}}}.wheel-core{{position:absolute;inset:190px;border-radius:50%;background:var(--deep);color:white;display:grid;place-content:center;text-align:center;z-index:2}}.wheel-core strong{{font-size:28px}}.wheel-core span{{font-size:13px;margin-top:7px}}.sat{{position:absolute;background:#fff;border:3px solid var(--orange);border-radius:50%;width:112px;height:112px;display:grid;place-items:center;font-weight:800;box-shadow:0 8px 22px #0001}}.s1{{left:40px;top:60px}}.s2{{right:2px;top:220px;border-color:var(--green)}}.s3{{left:80px;bottom:15px;border-color:var(--blue)}}.chart-slide{{grid-template-columns:40% 60%}}.narrative p{{font-size:18px;line-height:1.7;color:var(--muted)}}.metric-row{{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-top:45px}}.metric-row span{{border-left:4px solid var(--orange);padding:10px;background:#fff;font-size:13px}}.metric-row b{{display:block;font-size:27px;color:var(--deep)}}.funnel{{position:relative;height:520px;padding:54px 50px;background:#fff;border:1px solid var(--line);box-shadow:0 18px 50px #24342a12}}.f-row{{height:118px;display:grid;grid-template-columns:145px 1fr 100px;align-items:center;gap:18px}}.f-row label{{font-weight:800;font-size:18px}}.f-row small{{display:block;color:var(--muted);font-size:12px;margin-top:4px}}.f-row i{{display:block;width:var(--w);height:54px;background:linear-gradient(90deg,var(--orange),#f5b27d);transform-origin:left;animation:grow 1.2s ease both}}.f2 i{{background:linear-gradient(90deg,var(--green),#b7d39c);animation-delay:.15s}}.f3 i{{background:linear-gradient(90deg,var(--blue),#9ec3dc);animation-delay:.3s}}@keyframes grow{{from{{transform:scaleX(0)}}}}.f-row b{{font-size:27px}}.pulse-dot{{position:absolute;right:64px;bottom:40px;width:18px;height:18px;background:var(--orange);border-radius:50%;box-shadow:0 0 0 0 #ee7a2266;animation:pulse 1.8s infinite}}@keyframes pulse{{70%{{box-shadow:0 0 0 24px #ee7a2200}}}}.analysis-grid{{height:100%;display:grid;grid-template-columns:58% 42%;gap:24px}}.trend,.channel{{background:#fff;border:1px solid var(--line);padding:28px 30px;box-shadow:0 16px 38px #24342a10}}.chart-head{{display:flex;justify-content:space-between;align-items:flex-start}}.chart-head b{{font-size:20px}}.chart-head span{{font-size:12px;color:var(--muted)}}.trend svg{{width:100%;height:390px;margin-top:12px}}.grid path{{stroke:#dce2db;stroke-width:1}}.bars rect{{fill:#f2a05f;transform-origin:bottom;animation:barup 1s ease both}}.bars rect:nth-child(2){{animation-delay:.1s}}.bars rect:nth-child(3){{animation-delay:.2s}}.bars rect:nth-child(4){{animation-delay:.3s}}@keyframes barup{{from{{transform:scaleY(0)}}}}.line{{fill:none;stroke:var(--blue);stroke-width:5;stroke-dasharray:800;animation:draw 1.5s ease both}}@keyframes draw{{from{{stroke-dashoffset:800}}}}.dots circle{{fill:#fff;stroke:var(--blue);stroke-width:5}}.axis-label text{{font-size:15px;fill:#68716a}}.legend{{display:flex;align-items:center;gap:9px;color:#667067;font-size:13px}}.legend i{{width:20px;height:10px;background:#f2a05f;margin-left:12px}}.legend i:nth-of-type(2){{height:4px;background:var(--blue)}}.radar{{position:relative;width:330px;height:330px;margin:55px auto 25px}}.radar-grid,.radar-grid:before,.radar-grid:after{{position:absolute;inset:18px;content:"";clip-path:polygon(50% 0,100% 100%,0 100%);border:2px solid #cad5ca;background:linear-gradient(30deg,transparent 48%,#dbe2db 49%,#dbe2db 51%,transparent 52%)}}.radar-grid:before{{inset:48px}}.radar-grid:after{{inset:92px}}.radar-shape{{position:absolute;inset:65px 40px 38px;clip-path:polygon(50% 0,90% 82%,12% 100%);background:#ee7a2266;border:3px solid var(--orange);animation:fadein 1s}}@keyframes fadein{{from{{opacity:0;transform:scale(.65)}}}}.radar span{{position:absolute;text-align:center;font-size:13px}}.radar b{{font-size:19px}}.ra{{top:-12px;left:133px}}.rb{{right:-14px;bottom:14px}}.rc{{left:-14px;bottom:14px}}.channel p{{font-size:12px;color:var(--muted);text-align:center}}.experiment{{position:relative;height:100%;display:grid;grid-template-columns:220px 1fr 1fr;gap:38px;align-items:center}}.exp-source{{height:220px;background:var(--deep);color:#fff;display:grid;place-content:center;text-align:center;border-radius:50%;z-index:2}}.exp-source span,.exp-source small{{font-size:13px}}.exp-source b{{font-size:52px;margin:8px}}.stream{{position:absolute;left:195px;right:50px;top:48%;height:4px;background:#d6ded5}}.stream i{{position:absolute;width:13px;height:13px;background:var(--orange);border-radius:50%;top:-5px;animation:flow 3s linear infinite}}.stream i:nth-child(2){{animation-delay:-.75s}}.stream i:nth-child(3){{animation-delay:-1.5s}}.stream i:nth-child(4){{animation-delay:-2.25s}}@keyframes flow{{from{{left:0}}to{{left:100%}}}}.variant{{position:relative;height:410px;background:#fff;border-top:8px solid var(--orange);padding:30px;box-shadow:0 15px 38px #24342a18;z-index:2}}.variant.vb{{border-color:var(--blue)}}.variant em{{font-style:normal;font-size:54px;font-weight:900;color:#f4c099}}.variant.vb em{{color:#a5c9df}}.variant h3{{font-size:23px}}.variant p{{font-size:14px;color:var(--muted)}}.mini-bars{{height:170px;display:flex;align-items:end;gap:18px;border-bottom:1px solid var(--line)}}.mini-bars i{{width:42px;height:var(--h);background:linear-gradient(var(--orange),#f8d2b5);animation:barup 1s ease both}}.vb .mini-bars i{{background:linear-gradient(var(--blue),#cfe0ec)}}.gate{{position:absolute;left:250px;right:20px;bottom:0;background:#fff4e8;border:1px solid #f2c497;padding:14px 20px;display:flex;gap:28px}}.gate b{{color:#a94c12}}.gantt{{height:100%;background:#fff;border:1px solid var(--line);padding:26px 32px 70px;position:relative}}.g-head,.g-row{{display:grid;grid-template-columns:230px repeat(4,1fr);height:88px;align-items:center;border-bottom:1px solid #e1e5e0;position:relative}}.g-head{{height:54px;background:#f0f3ee}}.g-head b{{text-align:center;color:#677169}}.g-row strong{{font-size:18px}}.g-row small{{position:absolute;left:245px;top:57px;color:#6b746d;z-index:3}}.gbar{{height:28px;border-radius:16px;background:linear-gradient(90deg,var(--orange),#f7b17a);z-index:2;animation:grow 1.2s ease both}}.b1{{grid-column:2/3}}.b2{{grid-column:2/4;background:linear-gradient(90deg,#d99a58,#e7c07d)}}.b3{{grid-column:3/5;background:linear-gradient(90deg,var(--green),#b7d39c)}}.b4{{grid-column:5/6;background:linear-gradient(90deg,var(--blue),#9ec3dc)}}.milestones{{position:absolute;left:262px;right:32px;bottom:28px;height:28px;border-top:2px solid #d2d9d1}}.milestones span{{position:absolute;left:var(--x);transform:translateX(-50%);top:8px;font-size:12px;white-space:nowrap}}.milestones span:before{{content:"";position:absolute;width:10px;height:10px;background:var(--orange);border-radius:50%;top:-14px;left:50%}}.closing{{height:100%;display:grid;grid-template-columns:64% 36%;grid-template-rows:1fr 112px;gap:25px}}.close-main{{background:var(--deep);color:#fff;padding:58px 62px}}.close-main span{{color:#f3ad71;font-weight:800;font-size:13px;letter-spacing:.13em}}.close-main h3{{font-size:39px;line-height:1.35;max-width:820px;margin:35px 0}}.close-main p{{font-size:17px;color:#cad4cc;line-height:1.7}}.close-ring{{display:grid;place-items:center;background:#fff;border:1px solid var(--line)}}.close-ring>div{{width:265px;height:265px;border-radius:50%;display:grid;place-content:center;text-align:center;border:24px solid #f4b784;border-right-color:var(--blue);box-shadow:inset 0 0 0 2px #fff}}.close-ring b{{font-size:55px}}.close-ring span{{font-size:14px;color:var(--muted);line-height:1.4}}.next{{grid-column:1/3;display:grid;grid-template-columns:repeat(3,1fr);gap:15px}}.next span{{background:#fff;border-left:5px solid var(--orange);padding:25px;font-size:17px;font-weight:700}}.next b{{color:var(--orange);margin-right:16px}}#controls{{position:fixed;left:0;right:0;bottom:0;height:72px;background:#f8f8f5;display:flex;align-items:center;justify-content:center;gap:10px;border-top:1px solid #d9ddd7;z-index:20}}#controls button,#controls label{{font:inherit;border:1px solid #cfd5cf;background:#fff;padding:11px 17px;border-radius:7px;cursor:pointer}}#controls button:disabled{{opacity:.35}}#counter{{min-width:105px;text-align:center;color:#59635c}}#print-view{{display:none}}@media(prefers-reduced-motion:reduce){{*,*:before,*:after{{animation:none!important;transition:none!important}}}}@media print{{@page{{size:A4 landscape;margin:8mm}}html,body{{overflow:visible;background:#fff}}#viewport,#controls{{display:none}}#print-view{{display:block}}#print-view .slide{{position:relative;display:block;opacity:1;visibility:visible;width:1600px;height:900px;transform:scale(.68);transform-origin:top left;margin-bottom:-288px;break-after:page}}}}
</style></head><body><div id="viewport"><div id="deck">{slide_html}</div></div><nav id="controls"><button id="prev">← {controls[0]}</button><span id="counter"></span><button id="next">{controls[1]} →</button><label><input id="play" type="checkbox"> {controls[2]}</label><button id="restart">{controls[3]}</button><button id="print">{controls[4]}</button></nav><div id="print-view">{slide_html}</div><script type="application/json" id="full-data">{data}</script><script>
(()=>{{const slides=[...document.querySelectorAll('#deck .slide')],deck=document.querySelector('#deck'),vp=document.querySelector('#viewport'),counter=document.querySelector('#counter'),prev=document.querySelector('#prev'),next=document.querySelector('#next'),play=document.querySelector('#play');let at=0,timer=null;function fit(){{const s=Math.min(vp.clientWidth/1600,vp.clientHeight/900);deck.style.transform=`scale(${{s}})`}}function show(n){{at=Math.max(0,Math.min(slides.length-1,n));slides.forEach((s,i)=>s.classList.toggle('on',i===at));counter.textContent=`${{at+1}} / ${{slides.length}}`;prev.disabled=at===0;next.disabled=at===slides.length-1;if(at===slides.length-1)stop()}}function stop(){{clearInterval(timer);timer=null;play.checked=false}}function autoplay(){{stop();play.checked=true;timer=setInterval(()=>at<slides.length-1?show(at+1):stop(),7000)}}prev.onclick=()=>show(at-1);next.onclick=()=>show(at+1);play.onchange=()=>play.checked?autoplay():stop();document.querySelector('#restart').onclick=()=>{{stop();show(0)}};document.querySelector('#print').onclick=()=>{{stop();window.print()}};addEventListener('resize',fit);addEventListener('keydown',e=>{{if(e.key==='ArrowRight'||e.key==='PageDown')show(at+1);if(e.key==='ArrowLeft'||e.key==='PageUp')show(at-1);if(e.key==='Home')show(0);if(e.key==='End')show(slides.length-1);if(e.key.toLowerCase()==='a')play.checked?stop():autoplay()}});fit();show(0)}})();
</script></body></html>'''
    css_fix='<style>#viewport{display:block}#deck{position:absolute;left:50%;top:50%}.agenda-map{grid-template-columns:repeat(2,1fr);grid-template-rows:repeat(2,190px);gap:24px;align-content:center;padding-right:340px}.agenda-node{height:auto;padding:26px}.radar-grid{inset:42px;border:0;border-radius:50%;clip-path:none;background:conic-gradient(var(--orange) 0 39%,var(--blue) 39% 70%,var(--green) 70% 100%)}.radar-grid:before,.radar-grid:after{display:none}.radar-shape{inset:105px;border:0;border-radius:50%;clip-path:none;background:#fff}.ra{top:-5px}.rb{right:-8px;bottom:24px}.rc{left:-8px;bottom:24px}</style>'
    script_fix='''<script>(()=>{const d=document.querySelector('#deck'),v=document.querySelector('#viewport');function centerDeck(){const s=Math.min(v.clientWidth/1600,v.clientHeight/900);d.style.transform=`translate(-50%,-50%) scale(${s})`}addEventListener('resize',centerDeck);centerDeck()})();</script>'''
    return page.replace('</head>',css_fix+'</head>').replace('</body>',script_fix+'</body>')


def outputs():
    result = {}
    for language in ('ko', 'en'):
        value = deck(language)
        result[f'examples/full-presentation/deck.{language}.json'] = json.dumps(value, ensure_ascii=False, indent=2)+'\n'
        result[f'docs/full-presentation{ ".en" if language == "en" else "" }.html'] = render(language)
    return result


if __name__ == '__main__':
    for filename, content in outputs().items():
        target = ROOT / filename
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_text(content, encoding='utf8', newline='\n')
    print('Built bilingual seven-scene complete presentations.')
